/**
 * A fotossíntese — porte de `componentes/viz/fotossintese.js`.
 *
 * A folha não absorve luz onde ela precisa: absorve numa ANTENA de pigmentos
 * espalhada pela superfície e conduz a energia até um único centro de reação. O
 * controle é o tamanho dessa antena — a boca do funil. Fóton que cai dentro da
 * boca vira energia química; fóton que cai fora se perde como calor.
 *
 * A cena mostra as duas coisas ao mesmo tempo, porque é o contraste que ensina:
 * os captados descem verdes e convergem, os perdidos apagam em vermelho no meio
 * do caminho. Quando a captação basta, saem as bolhas de O₂ e o açúcar.
 */

import { criarCanvas2d } from '../../../viz/canvas2d.ts';
import {
  type EstadoDaViz,
  infoDe,
  limitar,
  numeroDe,
  paleta,
  retangulo,
  rodape,
  texto,
  titulo,
} from './desenho.ts';
import type { FabricaViz, VizDoPuzzle } from './index.ts';

/** Onde ficam os pigmentos da antena, em fração de (L, A). */
const PIGMENTOS: readonly (readonly [number, number])[] = [
  [0.28, 0.44],
  [0.4, 0.4],
  [0.52, 0.38],
  [0.64, 0.4],
  [0.74, 0.46],
  [0.36, 0.54],
  [0.5, 0.52],
  [0.62, 0.54],
  [0.44, 0.63],
  [0.56, 0.63],
];

const FOTONS = 14;

const fotossintese: FabricaViz = (canvas): VizDoPuzzle => {
  let estado: EstadoDaViz = {};

  /** Hexágono de ponta para cima — o pigmento, e também a molécula de açúcar. */
  function hexagono(ctx: CanvasRenderingContext2D, x: number, y: number, r: number): void {
    ctx.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = -Math.PI / 2 + (i * Math.PI) / 3;
      const px = x + r * Math.cos(a);
      const py = y + r * Math.sin(a);
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.closePath();
  }

  function desenhar(ctx: CanvasRenderingContext2D, L: number, A: number, t: number): void {
    const cor = paleta();
    const info = infoDe(estado);
    const valores = (estado.valores ?? {}) as Readonly<Record<string, unknown>>;

    const captacao = Math.max(0, numeroDe(valores, 'c', 0));
    const ok = info.ok === true;
    const eficiencia = numeroDe(info, 'efic', captacao) / 100;

    const solX = L * 0.5;
    const solY = A * 0.15;
    const centroX = L * 0.5;
    const centroY = A * 0.76;

    titulo(ctx, L, A, 'A antena que leva a luz ao centro');

    // A folha.
    ctx.fillStyle = 'rgb(28 92 52 / 22%)';
    ctx.beginPath();
    ctx.ellipse(L * 0.5, A * 0.62, L * 0.42, A * 0.3, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = 'rgb(28 92 52 / 45%)';
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // O sol e a luz disponível — o cone que desce e se abre.
    const bocaY = A * 0.44;
    ctx.beginPath();
    ctx.moveTo(solX - 6, solY + 10);
    ctx.lineTo(solX + 6, solY + 10);
    ctx.lineTo(centroX + L * 0.34, bocaY);
    ctx.lineTo(centroX - L * 0.34, bocaY);
    ctx.closePath();
    const feixe = ctx.createLinearGradient(0, solY, 0, bocaY);
    feixe.addColorStop(0, 'rgb(230 175 20 / 26%)');
    feixe.addColorStop(1, 'rgb(230 175 20 / 4%)');
    ctx.fillStyle = feixe;
    ctx.fill();

    ctx.fillStyle = cor.ouro;
    ctx.beginPath();
    ctx.arc(solX, solY, 14, 0, Math.PI * 2);
    ctx.fill();
    ctx.strokeStyle = cor.ouro;
    ctx.lineWidth = 2;
    for (let i = 0; i < 8; i++) {
      const a = t * 0.4 + (i * Math.PI) / 4;
      ctx.beginPath();
      ctx.moveTo(solX + Math.cos(a) * 18, solY + Math.sin(a) * 18);
      ctx.lineTo(solX + Math.cos(a) * 25, solY + Math.sin(a) * 25);
      ctx.stroke();
    }

    // A boca do funil: é ela que o controle abre e fecha.
    const boca = L * (0.05 + 0.3 * (captacao / 100));
    ctx.beginPath();
    ctx.moveTo(centroX - boca, bocaY);
    ctx.lineTo(centroX + boca, bocaY);
    ctx.lineTo(centroX + 6, centroY);
    ctx.lineTo(centroX - 6, centroY);
    ctx.closePath();
    ctx.fillStyle = ok ? 'rgb(47 143 92 / 26%)' : 'rgb(47 143 92 / 14%)';
    ctx.fill();
    ctx.strokeStyle = cor.verde;
    ctx.lineWidth = 1.5;
    ctx.stroke();

    // A cota da boca — sem ela o funil não lê como uma medida.
    ctx.strokeStyle = cor.texto;
    ctx.lineWidth = 1.4;
    ctx.beginPath();
    ctx.moveTo(centroX - boca, bocaY - 9);
    ctx.lineTo(centroX + boca, bocaY - 9);
    ctx.stroke();
    ctx.fillStyle = cor.texto;
    for (const lado of [-1, 1]) {
      ctx.beginPath();
      ctx.moveTo(centroX + lado * boca, bocaY - 9);
      ctx.lineTo(centroX + lado * (boca - 6), bocaY - 12);
      ctx.lineTo(centroX + lado * (boca - 6), bocaY - 6);
      ctx.closePath();
      ctx.fill();
    }
    texto(ctx, 'captação', centroX, bocaY - 20, limitar(A * 0.034, 8, 11), { cor: cor.fraco });

    // Os pigmentos: acesos dentro da boca, apagados fora dela.
    for (const [px, py] of PIGMENTOS) {
      const ativo = Math.abs(px * L - centroX) <= boca + 10;
      hexagono(ctx, px * L, py * A, 9);
      ctx.fillStyle = ativo ? cor.verde : 'rgb(70 120 90 / 35%)';
      ctx.fill();
      ctx.strokeStyle = cor.texto;
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    // Os fótons. A fração `eficiencia` é canalizada; o resto vira calor.
    for (let i = 0; i < FOTONS; i++) {
      const fase = (t * 0.5 + i / FOTONS) % 1;
      const captado = i / FOTONS < eficiencia;
      const colX = L * (0.22 + (i / FOTONS) * 0.56);

      if (captado) {
        let x: number;
        let y: number;
        if (fase < 0.6) {
          x = colX;
          y = solY + (centroY - solY) * (fase / 0.6) * 0.7;
        } else {
          const k = (fase - 0.6) / 0.4;
          const ay = solY + (centroY - solY) * 0.7;
          x = colX + (centroX - colX) * k;
          y = ay + (centroY - ay) * k;
        }
        ctx.fillStyle = cor.verde;
        ctx.globalAlpha = 0.9 * (1 - fase * 0.3);
        ctx.beginPath();
        ctx.arc(x, y, 3, 0, Math.PI * 2);
        ctx.fill();
      } else {
        ctx.fillStyle = cor.erro;
        ctx.globalAlpha = 0.7 * (1 - fase);
        ctx.beginPath();
        ctx.arc(colX, solY + A * 0.4 * fase, 3, 0, Math.PI * 2);
        ctx.fill();
      }
      ctx.globalAlpha = 1;
    }

    // O centro de reação, brilhando conforme o que lhe chega.
    const halo = ctx.createRadialGradient(centroX, centroY, 2, centroX, centroY, 26);
    halo.addColorStop(0, `rgb(47 143 92 / ${(0.25 + eficiencia * 0.4) * 100}%)`);
    halo.addColorStop(1, 'rgb(47 143 92 / 0%)');
    ctx.fillStyle = halo;
    ctx.beginPath();
    ctx.arc(centroX, centroY, 26, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = ok ? cor.verde : '#3f9b56';
    ctx.beginPath();
    ctx.arc(centroX, centroY, 9, 0, Math.PI * 2);
    ctx.fill();

    // Os produtos: só quando a folha de fato produz.
    if (ok) {
      for (let i = 0; i < 4; i++) {
        const fase = (t * 0.6 + i / 4) % 1;
        const bx = centroX + (i - 1.5) * 14;
        const by = centroY - fase * A * 0.36;

        ctx.globalAlpha = 0.85 * (1 - fase);
        ctx.fillStyle = cor.azulClaro;
        ctx.beginPath();
        ctx.arc(bx, by, 4, 0, Math.PI * 2);
        ctx.fill();
        texto(ctx, 'O₂', bx, by - 9, 8, { cor: cor.azul });
        ctx.globalAlpha = 1;
      }

      const saida = (t * 0.7) % 1;
      ctx.globalAlpha = 0.9 * (1 - saida);
      hexagono(ctx, centroX + 20 + saida * 40, centroY, 6);
      ctx.fillStyle = cor.ouro;
      ctx.fill();
      ctx.globalAlpha = 1;
    }

    // O medidor de eficiência.
    const gx = L - 14;
    const gy = A * 0.16;
    const gh = A * 0.62;
    retangulo(ctx, gx, gy, 9, gh, 4, cor.trilho);
    retangulo(
      ctx,
      gx,
      gy + gh * (1 - eficiencia),
      9,
      gh * eficiencia,
      4,
      ok ? cor.verde : cor.ouro,
    );

    const miudo = limitar(A * 0.034, 8, 11);
    texto(ctx, 'luz do Sol', solX + 30, solY - 4, miudo, { cor: cor.ouro, alinhamento: 'left' });
    texto(ctx, 'antena de clorofila', L * 0.06, A * 0.36, miudo, {
      cor: cor.fraco,
      alinhamento: 'left',
    });

    rodape(
      ctx,
      L,
      A,
      ok,
      'Açúcar + O₂ produzidos: luz virou vida ✔',
      `Eficiência ${Math.round(eficiencia * 100)}% — alargue a antena.`,
    );
  }

  const base = criarCanvas2d(canvas, {
    aoQuadro: (ctx, { L, A, t }) => desenhar(ctx, L, A, t),
  });

  return {
    aplicar(novo) {
      estado = novo;
    },
    redimensionar: base.redimensionar,
    pausar: base.pausar,
    retomar: base.retomar,
    destruir: base.destruir,
  };
};

export default fotossintese;
